 drivers/platform/chrome/cros_ec_proto_test.c | 151 +++++++++++++++++-
 2 files changed, 168 insertions(+), 8 deletions(-)

diff --git a/drivers/platform/chrome/cros_ec_proto.c
b/drivers/platform/chrome/cros_ec_proto.c
