+static bool ntb_direct_control_progress(struct ntb_transport_qp *qp)
+{
+	struct ntb_direct_shared *shared = qp->direct_shared;
+	u32 peer_session, session_ack, quiesce;
+	bool published = false;
+	bool cleanup = false;
+	bool ready = false;
