+	if (!qp->transport->link_is_up || !shared ||
+	    !qp->peer_direct_shared ||
+	    !ntb_direct_link_capable(qp) ||
+	    ntb_link_is_up(qp->ndev, NULL, NULL) != 1)
+		return true;
