+	peer_session = READ_ONCE(shared->session);
+	session_ack = READ_ONCE(shared->session_ack);
+	quiesce = READ_ONCE(shared->quiesce);
+
+	scoped_guard(spinlock_bh, &qp->direct_lock) {
+		if (!qp->direct_session)
+			goto out;
+
